DO $do$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['lab_results','critical_value_notifications','lab_trends','lab_qc_results','medication_reconciliation_workflows','medication_reconciliation_audit','lab_critical_acknowledgements','lab_critical_escalation_log','lab_critical_ranges','lab_result_notifications','lab_critical_alerts','break_glass_overrides','feature_flags','prescription_approval_workflows','audit_logs','system_metrics','lab_alert_escalations','discharge_workflows','discharge_workflow_tasks','drug_interactions','drug_interaction_cache','prescription_dur_reviews'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); END LOOP; END $do$; GRANT SELECT ON public.loinc_codes TO anon, authenticated; GRANT SELECT ON public.lab_interpretation_rules TO anon, authenticated; GRANT ALL ON public.loinc_codes TO service_role; GRANT ALL ON public.lab_interpretation_rules TO service_role; GRANT ALL ON public.lab_results TO service_role; GRANT ALL ON public.critical_value_notifications TO service_role; GRANT ALL ON public.lab_trends TO service_role; GRANT ALL ON public.lab_qc_results TO service_role;